#include "bits/stdc++.h"

using namespace std;

using ll = long long;

const int N = int(1e5) + 22;
multiset<int> t[4 * N];

void upd(int v, int l, int r, int i, int x, int k) {
    if (k == 1) t[v].insert(x);
    else t[v].erase(t[v].find(x));
    if (l + 1 < r) {
        int m = (l + r) / 2;
        if (i < m) upd(v * 2 + 1, l, m, i, x, k);
        else upd(v * 2 + 2, m, r, i, x, k);
    }
}

void get(int v, int l, int r, int l1, int r1, int x, int& ans) {
    if (l1 >= r || l >= r1) return;
    if (l1 <= l && r <= r1) {
        auto it = t[v].upper_bound(x);
        if (it != t[v].begin()) {
            it = prev(it);
            ans = max(ans, *it);
        }
        return;
    }
    int m = (l + r) / 2;
    get(v * 2 + 1, l, m, l1, r1, x, ans);
    get(v * 2 + 2, m, r, l1, r1, x, ans);
}

void solve () {
    int n, q;
    cin >> n >> q;
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        upd(0, 0, n, i, a[i], 1);
    }
    while (q--) {
        int tp;
        cin >> tp;
        if (tp == 1) {
            int i, x;
            cin >> i >> x;
            i--;
            upd(0, 0, n, i, a[i], -1);
            a[i] = x;
            upd(0, 0, n, i, a[i], 1);
        } else {
            int l, r, x;
            cin >> l >> r >> x;
            l--;
            while (1) {
                int z = -1;
                get(0, 0, n, l, r, x, z);
                if (z == -1) break;
                x %= z;
            }
            cout << x << '\n';
        }
    }
}

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    int t = 1;
//    cin >> t;
    while (t--) {
        solve();
    }
}
